INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65581351', 65581351, 'analyze_legacy', 'Kementerian Dalam Negeri', 'central', 'SEKRETARIAT JENDERAL', 'Pengadaan Plakat Wakil Menteri Dalam Negeri', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 200000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Dalam rangka mendukung kelancaran pelaksanaan tugas dan fungsi perkantoran, diperlukan penyediaan bahan logistik berupa plakat. Plakat digunakan sebagai bentuk penghargaan, kenangkenangan, maupun cinderamata pada kegiatan kedinasan dan hubungan kelembagaan. Agar penyediaan plakat dapat terencana, terarah, dan sesuai dengan ketentuan pengadaan barang/jasa pemerintah, maka disusunlah Kerangka Acuan Kerja (KAK) belanja plakat ini.', 'Plakat Wakil Menteri Dalam Negeri a. Kotak Luar - Kotak luar plakat berbentuk lipat dua (double frame) dan dibuat dari material kayu solid atau engineered wood berkualitas dengan finishing warna cokelat tua glossy. Kotak ini dirancang dengan konstruksi kokoh dan presisi, berfungsi sebagai pelindung utama sekaligus elemen estetika Rangka luar menggunakan material kayu solid/engineered wood finishing warna cokelat tua glossy, tebal 3,5 cm, panjang 19 cm, lebar 14 cm, warna coklat tua glossy, ditambahkan engsel dan kunci dari kuningan. b. Kotak Dalam - Bagian dalam plakat menggunakan panel kayu dengan finishing warna senada, dilengkapi bingkai dekoratif bermotif warna emas dan hitam yang mengelilingi area plat. Pada bagian tengah terdapat aksen penghubung berupa kain beludru berwarna biru yang berfungsi sebagai engsel sekaligus elemen visual, menciptakan tampilan yang rapi, simetris, dan menyatu dengan desain keseluruhan. c. Plat - Plat dalam menggunakan material logam berkualitas dengan warna dasar emas doff. Pada sisi kiri ditampilkan ilustrasi gedung Kementerian Dalam Negeri menggunakan teknik grafir atau etching dengan detail halus, garis ilustrasi berwarna hitam, serta pola lantai geometris berwarna emas tanpa pewarnaan hitam pada bidang lantai kecuali pada garis tepi sebagai penegasan. Pada sisi kanan ditampilkan logo resmi Kementerian Dalam Negeri berwarna penuh yang dilengkapi plat nama bertuliskan “WAKIL MENTERI DALAM NEGERI” berwarna biru pekat selaras dengan warna biru pada logo, dengan tulisan berwarna emas dan hasil pengerjaan yang rapi serta presisi. d. JumlahPlakat 250 Buah.', 50000000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2209467);
