INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65548213', 65548213, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'BANDAR UDARA MOZES KILANGIN TIMIKA', 'BIAYA PERPANJANGAN PAJAK KENDARAAN', 'Barang', 'Dikecualikan', 'Papua Tengah, Mimika (Kab.)', 165800000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '39 UNIT', '1 Biaya Perpanjangan Pajak Kendaraan Roda 2 28.800.000 2 Biaya Perpanjangan Pajak Kendaraan Roda 4 102.000.000 3 Biaya Perpanjangan Pajak Kendaraan Double Gardan 24.000.000 4 Biaya Perpanjangan Pajak Kendaraan Roda 6 6.000.000 5 Biaya Perpanjangan Pajak Kendaraan Roda 3 5.000.000', 'Pekerjaan biaya perpanjangan pajak kendaraan merupakan kegiatan pembayaran kewajiban tahunan Pajak Kendaraan Bermotor (PKB) dan/atau pengesahan Surat Tanda Nomor Kendaraan (STNK) atas kendaraan dinas operasional guna memastikan legalitas dan kepatuhan terhadap peraturan perundang-undangan yang berlaku. Ruang lingkup pekerjaan meliputi pengurusan dan pembayaran PKB tahunan, Sumbangan Wajib Dana Kecelakaan Lalu Lintas Jalan (SWDKLLJ), serta biaya administrasi lain yang sah sesuai ketentuan Samsat setempat, termasuk pengesahan STNK dan pencatatan masa berlaku pajak terbaru. Pelaksanaan kegiatan harus dilakukan sesuai data kendaraan (nomor polisi, nomor rangka, nomor mesin, dan masa berlaku pajak), dengan bukti pembayaran resmi dari instansi berwenang, sehingga kendaraan dinas dapat dioperasikan secara legal, aman, dan tidak menimbulkan risiko sanksi administratif dalam mendukung kelancaran tugas operasional.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2209755);
